CREATE OR REPLACE FUNCTION CMDKLTDA_LUIS_FN_SOMAR(
   p_num1 NUMBER,
   p_num2 NUMBER,
   p_num3 NUMBER
)
RETURN  NUMBER
IS
v number;
BEGIN
 RETURN p_num1  + p_num2 + p_num3 ;
END CMDKLTDA_LUIS_FN_SOMAR;
/

CREATE OR REPLACE PROCEDURE CMDKLTDA_LUIS_PRC_SOMAR(
   p_num1 NUMBER,
   p_num2 NUMBER
)
IS
v number;
BEGIN
V := CMDKLTDA_LUIS_FN_SOMAR(1,2,5);
END CMDKLTDA_LUIS_PRC_SOMAR;
/

